using System.Linq;using NUnit.Framework;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Rootborn.Game.Common;using Rootborn.Game.Player;using Rootborn.UI.Modern;namespace Rootborn.Tests.EditMode.UI.Modern{public sealed class UrbanInventoryStackCountLayoutTests{[TestCase(12)][TestCase(490)][TestCase(9999)]public void StackCountFitsInsideTheSlotMoldingAndRemainsExact(int quantity){var item=ScriptableObject.CreateInstance<ItemDefinition>();var data=new SerializedObject(item);data.FindProperty("_id").stringValue="fixture.stack-count";data.FindProperty("_displayKey").stringValue="Fixture";data.FindProperty("_maxStack").intValue=9999;data.ApplyModifiedPropertiesWithoutUndo();var player=new GameObject("StackFixture",typeof(PlayerInventory));var root=new GameObject("Inventory",typeof(RectTransform));try{var inventory=player.GetComponent<PlayerInventory>();inventory.Inventory.Add(item,quantity);var panel=root.AddComponent<ModernUiInventoryPanel>();panel.Bind(inventory);panel.Show();var slot=(RectTransform)root.GetComponentsInChildren<ScrollRect>().Single().content.GetChild(0);var label=slot.Find("Count").GetComponent<Text>();Assert.That(label.text,Is.EqualTo(quantity.ToString()));var inner=slot.rect;inner.xMin+=16;inner.xMax-=16;inner.yMin+=16;inner.yMax-=16;var corners=new Vector3[4];label.rectTransform.GetWorldCorners(corners);foreach(var c in corners)Assert.That(inner.Contains(slot.InverseTransformPoint(c)),Is.True,"Stack label must stay inside the slot's inner frame");Assert.That(label.preferredWidth,Is.LessThanOrEqualTo(label.rectTransform.rect.width+2),"Four-digit stacks must remain readable");Assert.That(inventory.Inventory.CountOf(item),Is.EqualTo(quantity));}finally{Object.DestroyImmediate(root);Object.DestroyImmediate(player);Object.DestroyImmediate(item);}}}}
